import React, { useState } from "react";
import styled from "styled-components";

const ListContainer = styled.div`
  width: 100%;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow-y: auto;
`;

const Title = styled.h3`
  font-size: 32px;
  font-weight: bold;
  margin-bottom: 20px;
  text-align: center;
`;

const RecordGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  width: 100%;
`;

const RecordField = styled.div`
  font-size: 16px;
  word-break: break-word;
`;

const FullWidthField = styled.div`
  grid-column: span 3;
  font-size: 16px;
  margin-top: 10px;
`;

const EyeIcon = styled.span`
  cursor: pointer;
  font-size: 18px;
  color: #007bff;
  &:hover {
    text-decoration: underline;
  }
`;

const NucleicContainer = styled.div`
  margin-top: 8px;
  word-break: break-word;
  max-width: 400px;
  font-family: monospace;
  background: #f1f1f1;
  padding: 10px;
  border-radius: 5px;
`;

const VirulenceListResult = ({ label, data }) => {
  const [visibleRows, setVisibleRows] = useState({});

  let groups = {
    "Nucleoid (DNA)": ["Quorom sensing", "T6SS"],
    "Ribosomes": ["Capsule", "Phospholipase C"],
    "Cytoplasm": ["LPS", "HemO cluster"],
    "Plasmid": ["TFP", "T2SS"],
    "Pili": ["PbpG", "Acinetobactin"],
    "Inclusion Bodies": ["Csu fimbriae", "Phospholipase D"],
    "Flagellum": ["PNAG", "Bap"],
    "Cytoplasmic Membrane": ["BfmRS", "AdeFGH efflux pump"],
    "Cell Wall": ["OmpA"]
  }
  let group = groups[label];
  let filterdata = [];
  group.forEach((item) => {
    filterdata.push(data.filter((dataItem) => dataItem.group === item));
  });
  filterdata = filterdata.flat(); 
  const toggleNucleic = (index) => {
    setVisibleRows((prev) => ({
      ...prev,
      [index]: !prev[index],
    }));
  };

  return (
    <ListContainer>
      <Title>{label}</Title>
      {filterdata.map((item, index) => (
            <RecordContainer key={index}>
                <RecordGrid>
                <RecordField><strong>Index:</strong> {index + 1}</RecordField>
                <RecordField><strong>Sequence:</strong> {item.sequence}</RecordField>
                <RecordField><strong>Gene:</strong> {item.gene}</RecordField>

                <RecordField><strong>Start:</strong> {item.start}</RecordField>
                <RecordField><strong>Stop:</strong> {item.stop}</RecordField>
                <RecordField><strong>Strand:</strong> {item.strand}</RecordField>

                <RecordField><strong>Identity (%):</strong> {item.identity}</RecordField>
                <RecordField><strong>Coverage (%):</strong> {item.coverage}</RecordField>
                <RecordField><strong>Accession:</strong> {item.accession}</RecordField>

                <RecordField><strong>Description:</strong> {item.description || "N/A"}</RecordField>
                <RecordField><strong>Group:</strong> {item.group || "N/A"}</RecordField>
                <RecordField><strong>VFDB ID:</strong> {item.vfdb_id || "N/A"}</RecordField>

                <RecordField><strong>Function Group:</strong> {item.function_group || "N/A"}</RecordField>
                <RecordField><strong>Function Group ID:</strong> {item.function_group_id || "N/A"}</RecordField>

                <FullWidthField>
                    <strong>Nucleic:</strong>
                    <EyeIcon onClick={() => toggleNucleic(index)}>
                    {visibleRows[index] ? "🙈" : "👁️"}
                    </EyeIcon>
                    {visibleRows[index] && (
                    <NucleicContainer>{item.nucleic || "N/A"}</NucleicContainer>
                    )}
                </FullWidthField>
                </RecordGrid>
            </RecordContainer>
            ))}

    </ListContainer>
  );
};

export default VirulenceListResult;
